{
  "story": "Gas-bearing magma collects in the Magma reservoir beneath a blocked Conduit. Advance to see pressure open the Conduit. At the Vent, falling pressure lets gas expand and drive magma out as lava. This simplified example shows a gas-driven eruption.",
  "aha": {
    "stateId": "eruption",
    "observation": "As magma rises, falling pressure lets gas expand, helping drive magma through the Vent as lava."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "eruption-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell, with explanation and instructions above the experiment. Show progress only on this rail. Parameter-control budget: zero; navigation: Previous, Next, Reset.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "volcano-picture",
      "kind": "fixed-picture",
      "presentation": "Fixed cross-section: Magma reservoir below Conduit, with Vent at the surface. Keep labels readable and highlight one region at a time. Links indicate connections, not animated flow.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "active-location",
      "kind": "active-callout",
      "presentation": "Anchor beside the active region without covering labels. The callout identifies the location and explains the mechanism.",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "eruption-status",
      "kind": "value-readout",
      "presentation": "Bound status line below the picture. Use qualitative observations, not a fabricated clock.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stage",
      "kind": "index",
      "presentation": "Default to the first state; advance one state per action. Label buttons Previous and Next, retaining names when disabled at boundaries. Every state, including eruption, persists until learner action. Reference captures show eruption. Provide visible focus and keyboard operation.",
      "items": "variant.states",
      "label": "Eruption stage"
    },
    {
      "id": "reset",
      "kind": "reset",
      "presentation": "Restore the first state and all defaults. Provide visible focus and keyboard operation.",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Simplified gas-driven eruption",
        "regions": [
          {
            "id": "reservoir",
            "label": "Magma reservoir",
            "values": [
              "Gas-bearing molten rock underground"
            ]
          },
          {
            "id": "conduit",
            "label": "Conduit",
            "values": [
              "Passage through surrounding rock"
            ]
          },
          {
            "id": "vent",
            "label": "Vent",
            "values": [
              "Opening at the surface"
            ]
          }
        ],
        "links": [
          {
            "from": "reservoir",
            "to": "conduit",
            "label": "Underground connection"
          },
          {
            "from": "conduit",
            "to": "vent",
            "label": "Route to the surface"
          }
        ],
        "states": [
          {
            "id": "pressure-builds",
            "label": "Pressure builds",
            "short": "Trapped",
            "sentence": "Magma reservoir",
            "why": "Magma and gas accumulate beneath a blocked Conduit, increasing pressure against the surrounding rock.",
            "active": [
              "reservoir"
            ],
            "calloutRegion": "reservoir",
            "readouts": [
              {
                "id": "status",
                "label": "Status",
                "value": "Conduit blocked; magma remains underground."
              }
            ]
          },
          {
            "id": "path-opens",
            "label": "A path opens",
            "short": "Rising",
            "sentence": "Conduit",
            "why": "Pressure overcomes the rock's resistance, opening a path upward; pressure on the rising magma then decreases.",
            "active": [
              "conduit"
            ],
            "calloutRegion": "conduit",
            "readouts": [
              {
                "id": "status",
                "label": "Status",
                "value": "Conduit open; magma rises toward the Vent."
              }
            ]
          },
          {
            "id": "eruption",
            "label": "Eruption",
            "short": "Gas expands",
            "sentence": "Vent",
            "why": "Lower pressure lets gas bubbles expand, helping push magma out; magma at the surface is called lava.",
            "active": [
              "vent"
            ],
            "calloutRegion": "vent",
            "readouts": [
              {
                "id": "status",
                "label": "Status",
                "value": "Expanding gas drives magma through the Vent as lava."
              }
            ]
          }
        ]
      }
    ]
  }
}
